#[test]
fn age_field_case_2_no_boundary() {
    // Degenerate: no boundary cells at all -- maxd stays clamped at 1e-6,
    // every raw distance (1e9) divides to something huge, min(1, ...) clamps
    // every cell to exactly 1.0.
    let boundary_mask: Vec<u8> = vec![0; 30];
    let expected: Vec<f32> = vec![1.0; 30];
    assert_eq!(build_age_field(6, 5, &boundary_mask), expected);
}
